"use client";

import type { ComponentProps, ComponentType } from "react";

import {
  ArrowDown as ArrowDownRaw,
  ArrowLeft as ArrowLeftRaw,
  ArrowRight as ArrowRightRaw,
  ArrowsLeftRight,
  CalendarBlank,
  Compass,
  PaperPlaneRight,
  SealCheck,
  X as XRaw,
  type IconProps,
} from "@phosphor-icons/react";

/**
 * Os ícones do app — o vocabulário inteiro, num arquivo só.
 *
 * Por que este arquivo existe: a diferença entre os nossos ícones e os do
 * Discord nunca foi de desenho, foi de **peso**. O conjunto deles é sólido,
 * preenchido, de terminações arredondadas; o lucide, que usávamos, é de
 * contorno com traço uniforme. Acertar a forma de cada ícone não adianta
 * enquanto a família inteira for vazada — é a propriedade que atravessa o
 * conjunto que faz a tela parecer de outro produto.
 *
 * O grosso do vocabulário vem hoje dos **ativos do próprio Discord** (ver
 * `doDiscord` no fim do arquivo). O que ele não tem cai no Phosphor (MIT), que
 * tem peso `fill` com o mesmo arredondado; o que nem o Phosphor tem cai no
 * lucide. O peso do Phosphor é definido **uma vez** pelo `IconContext` (ver
 * `PesoDosIcones`), e não em cada chamada: um `weight="fill"` esquecido num
 * ícone só apareceria como um contorno solitário no meio da barra.
 *
 * Este arquivo é o **único** ponto de importação de ícone do app. Nenhum
 * arquivo de consumo importa de `lucide-react` ou do `@phosphor-icons/react`
 * direto — é o que permite trocar a origem de um ícone mexendo numa linha só.
 *
 * Os nomes continuam os do lucide de propósito. São ~60 pontos de uso; renomear
 * tudo junto misturaria a mudança visual, que se revisa olhando, com um
 * renomear mecânico, que se revisa lendo. Quando o resto do app migrar, os
 * nomes viram os do Phosphor de uma vez.
 */

/**
 * ── O que ainda vem do Phosphor ───────────────────────────────────────────
 *
 * Não por princípio: **por falta de ativo**. Tudo o que existe no acervo do
 * Discord vem de lá; o que sobra aqui é o que ele não desenhou.
 *
 * Estes são pictogramas, então herdam o `fill` do `IconContext` como o resto.
 * A última linha é do lucide, que é de contorno e vai destoar um pouco — é o preço de não ter equivalente em lugar nenhum, e some quando
 * aparecer ativo ou equivalente melhor.
 */
export {
  Airplane as Plane,
  Archive,
  BellRinging as BellRing,
  Camera,
  ChartBar as BarChart3,
  Coffee,
  DownloadSimple as Download,
  FileText,
  Gauge,
  PaintBrush as Paintbrush,
  Paperclip,
  PersonArmsSpread as Accessibility,
  PushPinSlash as PinOff,
  Radio,
  ShieldCheck,
  ShieldSlash as ShieldOff,
  ShieldWarning as ShieldAlert,
  SmileyAngry as Angry,
  SmileyMeh as Annoyed,
  Translate as Languages,
  UserCircle,
} from "@phosphor-icons/react";

export { ArchiveRestore, Laugh, TimerOff } from "lucide-react";

/**
 * O Discord **não** é uniformemente preenchido, e foi isso que eu errei ao
 * ligar `fill` para tudo de uma vez.
 *
 * Os pictogramas dele — pessoa, microfone, fone, engrenagem — são sólidos. As
 * **marcas utilitárias** — o `+`, o `×`, as setas, a lupa — são traço. São
 * classes diferentes de sinal: o pictograma nomeia uma coisa e precisa de corpo
 * para ser reconhecido; a marca utilitária é gesto puro, e engordá-la a
 * transforma num carimbo que grita mais alto que o nome do item ao lado.
 *
 * O que mudou: marca utilitária **não** fica no Phosphor por princípio. Fica
 * quando não há ativo no acervo. As que há — a lupa, o `+`, os chevrons, os
 * pontinhos, o duplo-visto — passaram para o Discord, porque os ativos dele
 * para essas justamente **são de traço**: dá para ter o desenho dele e o peso
 * certo ao mesmo tempo, que era o impasse. Sobrou aqui o `×`, que no acervo só
 * existe dentro de um círculo, e as setas, cujos "arrow-*" de lá são chevrons.
 *
 * `bold` e não `regular` porque o resto da interface é sólido: traço fino
 * demais ao lado de pictograma cheio lê como ícone de outra família.
 *
 * O `weight` vem **antes** do spread de propósito: quem chamar pode sobrescrever.
 */
function traco<P extends IconProps>(Icone: ComponentType<P>) {
  return function MarcaDeTraco(props: P) {
    return <Icone weight="bold" {...props} />;
  };
}

export const X = traco(XRaw);
export const ArrowLeft = traco(ArrowLeftRaw);
export const ArrowRight = traco(ArrowRightRaw);
export const ArrowDown = traco(ArrowDownRaw);
export const ArrowLeftRight = traco(ArrowsLeftRight);
export const SendHorizonal = traco(PaperPlaneRight);

